-- Reference psql variables for the queries below:
\set service 'orders'
\set environment 'test'
\set branch ''

CREATE TABLE IF NOT EXISTS resq_runs (
  run_id TEXT NOT NULL,
  started_at TIMESTAMPTZ NOT NULL,
  finished_at TIMESTAMPTZ NOT NULL,
  duration_seconds DOUBLE PRECISION NOT NULL,
  framework_version TEXT NOT NULL,
  hostname TEXT NOT NULL,
  q_version TEXT NOT NULL,
  os TEXT NOT NULL,
  test_count BIGINT NOT NULL,
  pass_count BIGINT NOT NULL,
  fail_count BIGINT NOT NULL,
  error_count BIGINT NOT NULL,
  skip_count BIGINT NOT NULL,
  assertion_count BIGINT NOT NULL,
  labels JSONB NOT NULL,
  environment TEXT NOT NULL,
  service TEXT NOT NULL,
  deployment_id TEXT NOT NULL,
  artifact_digest TEXT NOT NULL,
  vcs_sha TEXT NOT NULL,
  vcs_branch TEXT NOT NULL,
  ci_provider TEXT NOT NULL,
  ci_pipeline_id TEXT NOT NULL,
  raw_payload JSONB NOT NULL,
  PRIMARY KEY (run_id)
);
CREATE TABLE IF NOT EXISTS resq_tests (
  run_id TEXT NOT NULL,
  execution_id TEXT NOT NULL,
  test_id TEXT NOT NULL,
  case_id TEXT NOT NULL,
  suite TEXT NOT NULL,
  description TEXT NOT NULL,
  kind TEXT NOT NULL,
  status TEXT NOT NULL,
  duration_seconds DOUBLE PRECISION NOT NULL,
  asserts_run BIGINT NOT NULL,
  attempts BIGINT NOT NULL,
  retried BOOLEAN NOT NULL,
  flaky BOOLEAN NOT NULL,
  file_path TEXT NOT NULL,
  line BIGINT,
  message TEXT NOT NULL,
  quarantine_state TEXT,
  quarantine_active BOOLEAN,
  quarantine_owner TEXT,
  quarantine_reason TEXT,
  quarantine_issue TEXT,
  quarantine_expires_at TIMESTAMPTZ,
  raw_payload JSONB NOT NULL,
  PRIMARY KEY (run_id, execution_id),
  FOREIGN KEY (run_id) REFERENCES resq_runs (run_id)
);
CREATE TABLE IF NOT EXISTS resq_attempts (
  run_id TEXT NOT NULL,
  execution_id TEXT NOT NULL,
  attempt_key TEXT NOT NULL,
  attempt BIGINT NOT NULL,
  status TEXT NOT NULL,
  duration_seconds DOUBLE PRECISION NOT NULL,
  started_at TIMESTAMPTZ,
  finished_at TIMESTAMPTZ,
  asserts_run BIGINT NOT NULL,
  message TEXT NOT NULL,
  raw_payload JSONB NOT NULL,
  PRIMARY KEY (attempt_key),
  FOREIGN KEY (run_id, execution_id) REFERENCES resq_tests (run_id, execution_id)
);
CREATE TABLE IF NOT EXISTS resq_benchmarks (
  run_id TEXT NOT NULL,
  benchmark_id TEXT NOT NULL,
  test_id TEXT NOT NULL,
  suite TEXT NOT NULL,
  description TEXT NOT NULL,
  metric TEXT NOT NULL,
  unit TEXT NOT NULL,
  runs BIGINT NOT NULL,
  avg_time_ms DOUBLE PRECISION,
  med_time_ms DOUBLE PRECISION,
  max_time_ms DOUBLE PRECISION,
  avg_space_bytes DOUBLE PRECISION,
  comparison_class TEXT NOT NULL,
  raw_payload JSONB NOT NULL,
  PRIMARY KEY (run_id, benchmark_id),
  FOREIGN KEY (run_id) REFERENCES resq_runs (run_id)
);
CREATE TABLE IF NOT EXISTS resq_diagnostics (
  run_id TEXT NOT NULL,
  diagnostic_key TEXT NOT NULL,
  type TEXT NOT NULL,
  severity TEXT NOT NULL,
  phase TEXT NOT NULL,
  message TEXT NOT NULL,
  data JSONB NOT NULL,
  raw_payload JSONB NOT NULL,
  PRIMARY KEY (diagnostic_key),
  FOREIGN KEY (run_id) REFERENCES resq_runs (run_id)
);
CREATE TABLE IF NOT EXISTS resq_coverage_runs (
  run_id TEXT NOT NULL,
  functions_found BIGINT NOT NULL,
  functions_hit BIGINT NOT NULL,
  function_percent DOUBLE PRECISION NOT NULL,
  lines_found BIGINT NOT NULL,
  lines_hit BIGINT NOT NULL,
  line_percent DOUBLE PRECISION NOT NULL,
  statement_sites_found BIGINT NOT NULL,
  statement_sites_hit BIGINT NOT NULL,
  statement_site_percent DOUBLE PRECISION NOT NULL,
  statement_site_instrumentation_percent DOUBLE PRECISION NOT NULL,
  statement_site_instrumentation_complete BOOLEAN NOT NULL,
  branches_found BIGINT NOT NULL,
  branches_hit BIGINT NOT NULL,
  branch_percent DOUBLE PRECISION NOT NULL,
  branch_instrumentation_percent DOUBLE PRECISION NOT NULL,
  branch_instrumentation_complete BOOLEAN NOT NULL,
  function_instrumentation_percent DOUBLE PRECISION NOT NULL,
  statement_instrumentation_percent DOUBLE PRECISION NOT NULL,
  statement_instrumentation_complete BOOLEAN NOT NULL,
  raw_payload JSONB NOT NULL,
  PRIMARY KEY (run_id),
  FOREIGN KEY (run_id) REFERENCES resq_runs (run_id)
);
CREATE TABLE IF NOT EXISTS resq_coverage_files (
  run_id TEXT NOT NULL,
  coverage_file_key TEXT NOT NULL,
  file_path TEXT NOT NULL,
  loaded BOOLEAN NOT NULL,
  function_found BIGINT NOT NULL,
  function_hit BIGINT NOT NULL,
  line_found BIGINT NOT NULL,
  line_hit BIGINT NOT NULL,
  raw_payload JSONB NOT NULL,
  PRIMARY KEY (coverage_file_key),
  FOREIGN KEY (run_id) REFERENCES resq_runs (run_id)
);
CREATE TABLE IF NOT EXISTS resq_coverage_functions (
  run_id TEXT NOT NULL,
  coverage_file_key TEXT NOT NULL,
  coverage_function_key TEXT NOT NULL,
  file_path TEXT NOT NULL,
  function_name TEXT NOT NULL,
  line BIGINT NOT NULL,
  hits BIGINT NOT NULL,
  covered BOOLEAN NOT NULL,
  raw_payload JSONB NOT NULL,
  PRIMARY KEY (coverage_function_key),
  FOREIGN KEY (coverage_file_key) REFERENCES resq_coverage_files (coverage_file_key)
);
CREATE TABLE IF NOT EXISTS resq_coverage_sites (
  run_id TEXT NOT NULL,
  coverage_file_key TEXT NOT NULL,
  coverage_function_key TEXT NOT NULL,
  coverage_site_key TEXT NOT NULL,
  site_id TEXT NOT NULL,
  kind TEXT NOT NULL,
  file_path TEXT NOT NULL,
  function_name TEXT NOT NULL,
  line BIGINT,
  column_number BIGINT,
  eligible BOOLEAN NOT NULL,
  instrumented BOOLEAN NOT NULL,
  hits BIGINT,
  edges_hit BIGINT,
  raw_payload JSONB NOT NULL,
  PRIMARY KEY (coverage_site_key),
  FOREIGN KEY (coverage_file_key) REFERENCES resq_coverage_files (coverage_file_key)
);
CREATE TABLE IF NOT EXISTS resq_coverage_edges (
  run_id TEXT NOT NULL,
  coverage_site_key TEXT NOT NULL,
  coverage_edge_key TEXT NOT NULL,
  edge_id TEXT NOT NULL,
  label TEXT NOT NULL,
  hits BIGINT NOT NULL,
  covered BOOLEAN NOT NULL,
  raw_payload JSONB NOT NULL,
  PRIMARY KEY (coverage_edge_key),
  FOREIGN KEY (coverage_site_key) REFERENCES resq_coverage_sites (coverage_site_key)
);
CREATE TABLE IF NOT EXISTS resq_coverage_contexts (
  run_id TEXT NOT NULL,
  coverage_context_key TEXT NOT NULL,
  context_id TEXT NOT NULL,
  kind TEXT NOT NULL,
  test_id TEXT NOT NULL,
  attempt BIGINT NOT NULL,
  suite TEXT NOT NULL,
  description TEXT NOT NULL,
  file_path TEXT NOT NULL,
  raw_payload JSONB NOT NULL,
  PRIMARY KEY (coverage_context_key),
  FOREIGN KEY (run_id) REFERENCES resq_runs (run_id)
);
CREATE TABLE IF NOT EXISTS resq_coverage_context_metrics (
  run_id TEXT NOT NULL,
  coverage_context_key TEXT NOT NULL,
  metric_id TEXT NOT NULL,
  kind TEXT NOT NULL,
  coverage_file_key TEXT NOT NULL,
  coverage_site_key TEXT NOT NULL,
  function_name TEXT NOT NULL,
  edge_index BIGINT,
  edge_label TEXT NOT NULL,
  hits BIGINT NOT NULL,
  raw_payload JSONB NOT NULL,
  PRIMARY KEY (run_id, coverage_context_key, metric_id),
  FOREIGN KEY (coverage_context_key) REFERENCES resq_coverage_contexts (coverage_context_key)
);

-- query:services — Services
SELECT DISTINCT service AS __text, service AS __value FROM resq_runs WHERE service <> '' ORDER BY service;

-- query:environments — Environments
SELECT DISTINCT environment AS __text, environment AS __value FROM resq_runs WHERE environment <> '' AND (:'service' = '' OR service = :'service') ORDER BY environment;

-- query:branches — Branches
SELECT DISTINCT vcs_branch AS __text, vcs_branch AS __value FROM resq_runs WHERE vcs_branch <> '' AND (:'service' = '' OR service = :'service') ORDER BY vcs_branch;

-- query:tests_list — Tests
SELECT DISTINCT t.suite || ' :: ' || t.description ||
       CASE WHEN t.case_id <> '' THEN ' [case]' ELSE '' END AS __text,
       t.execution_id AS __value
FROM resq_tests AS t JOIN resq_runs AS r ON r.run_id = t.run_id
WHERE (:'service' = '' OR r.service = :'service') AND (:'environment' = '' OR r.environment = :'environment') AND (:'branch' = '' OR r.vcs_branch = :'branch') ORDER BY __text LIMIT 2000;

-- query:benchmarks_list — Benchmarks
SELECT DISTINCT b.suite || ' :: ' || b.description AS __text,
       b.benchmark_id AS __value
FROM resq_benchmarks AS b JOIN resq_runs AS r ON r.run_id = b.run_id
WHERE (:'service' = '' OR r.service = :'service') AND (:'environment' = '' OR r.environment = :'environment') AND (:'branch' = '' OR r.vcs_branch = :'branch') ORDER BY __text LIMIT 500;

-- query:headline_trend — Latest run headline
SELECT r.finished_at AS time, r.test_count,
       r.fail_count + r.error_count AS failures,
       CASE WHEN r.test_count = 0 THEN 100.0 ELSE 100.0 * r.pass_count / r.test_count END AS pass_rate,
       (SELECT COUNT(*) FROM resq_tests AS t WHERE t.run_id = r.run_id AND t.flaky) AS flaky_count,
       (SELECT COUNT(*) FROM resq_tests AS t WHERE t.run_id = r.run_id AND t.quarantine_active) AS active_quarantines,
       (SELECT c.function_percent FROM resq_coverage_runs AS c WHERE c.run_id = r.run_id) AS function_percent
FROM resq_runs AS r WHERE (:'service' = '' OR r.service = :'service') AND (:'environment' = '' OR r.environment = :'environment') AND (:'branch' = '' OR r.vcs_branch = :'branch')
ORDER BY r.finished_at;

-- query:pass_rate — Pass rate
SELECT r.finished_at AS time,
       CASE WHEN r.test_count = 0 THEN 100.0 ELSE 100.0 * r.pass_count / r.test_count END AS pass_rate
FROM resq_runs AS r WHERE (:'service' = '' OR r.service = :'service') AND (:'environment' = '' OR r.environment = :'environment') AND (:'branch' = '' OR r.vcs_branch = :'branch')
ORDER BY r.finished_at;

-- query:failure_breakdown — Failures, errors, flakes, skips
SELECT r.finished_at AS time, r.fail_count AS failed, r.error_count AS errored,
       r.skip_count AS skipped,
       (SELECT COUNT(*) FROM resq_tests AS t
         WHERE t.run_id = r.run_id AND t.flaky) AS flaky
FROM resq_runs AS r WHERE (:'service' = '' OR r.service = :'service') AND (:'environment' = '' OR r.environment = :'environment') AND (:'branch' = '' OR r.vcs_branch = :'branch')
ORDER BY r.finished_at;

-- query:run_duration — Run duration
SELECT r.finished_at AS time, r.duration_seconds
FROM resq_runs AS r WHERE (:'service' = '' OR r.service = :'service') AND (:'environment' = '' OR r.environment = :'environment') AND (:'branch' = '' OR r.vcs_branch = :'branch')
ORDER BY r.finished_at;

-- query:test_volume — Tests and assertions per run
SELECT r.finished_at AS time, r.test_count AS tests, r.assertion_count AS assertions
FROM resq_runs AS r WHERE (:'service' = '' OR r.service = :'service') AND (:'environment' = '' OR r.environment = :'environment') AND (:'branch' = '' OR r.vcs_branch = :'branch')
ORDER BY r.finished_at;

-- query:coverage_trend — Coverage by basis
SELECT r.finished_at AS time, c.function_percent, c.line_percent,
       c.statement_site_percent, c.branch_percent
FROM resq_coverage_runs AS c JOIN resq_runs AS r ON r.run_id = c.run_id
WHERE (:'service' = '' OR r.service = :'service') AND (:'environment' = '' OR r.environment = :'environment') AND (:'branch' = '' OR r.vcs_branch = :'branch')
ORDER BY r.finished_at;

-- query:coverage_completeness — Instrumentation completeness
SELECT r.finished_at AS time,
       c.statement_site_instrumentation_percent AS statement_completeness,
       c.branch_instrumentation_percent AS branch_completeness
FROM resq_coverage_runs AS c JOIN resq_runs AS r ON r.run_id = c.run_id
WHERE (:'service' = '' OR r.service = :'service') AND (:'environment' = '' OR r.environment = :'environment') AND (:'branch' = '' OR r.vcs_branch = :'branch')
ORDER BY r.finished_at;

-- query:coverage_drops — Coverage drops vs previous covered run
WITH history AS (
    SELECT f.file_path, r.finished_at,
           CASE WHEN f.function_found = 0 THEN 100.0
                ELSE 100.0 * f.function_hit / f.function_found END AS function_percent,
           LAG(CASE WHEN f.function_found = 0 THEN 100.0
                ELSE 100.0 * f.function_hit / f.function_found END) OVER (
               PARTITION BY f.file_path ORDER BY r.finished_at) AS previous_percent
    FROM resq_coverage_files AS f JOIN resq_runs AS r ON r.run_id = f.run_id
    WHERE (:'service' = '' OR r.service = :'service') AND (:'environment' = '' OR r.environment = :'environment') AND (:'branch' = '' OR r.vcs_branch = :'branch'))
SELECT h.file_path, h.previous_percent, h.function_percent,
       h.function_percent - h.previous_percent AS change
FROM history AS h
WHERE h.finished_at = (
    SELECT MAX(r2.finished_at) FROM resq_runs AS r2
    JOIN resq_coverage_runs AS c2 ON c2.run_id = r2.run_id WHERE (:'service' = '' OR r2.service = :'service') AND (:'environment' = '' OR r2.environment = :'environment') AND (:'branch' = '' OR r2.vcs_branch = :'branch'))
  AND h.previous_percent IS NOT NULL
  AND h.function_percent < h.previous_percent
ORDER BY change, h.file_path LIMIT 25;

-- query:daily_duration — Daily run duration (avg/max)
SELECT MIN(r.finished_at) AS time,
       AVG(r.duration_seconds) AS avg_seconds,
       MAX(r.duration_seconds) AS max_seconds
FROM resq_runs AS r WHERE (:'service' = '' OR r.service = :'service') AND (:'environment' = '' OR r.environment = :'environment') AND (:'branch' = '' OR r.vcs_branch = :'branch')
GROUP BY SUBSTR(CAST(r.finished_at AS TEXT), 1, 10)
ORDER BY time;

-- query:coverage_files_latest — Least-covered files (latest run)
SELECT f.file_path, f.function_hit, f.function_found,
       CASE WHEN f.function_found = 0 THEN 100.0
            ELSE 100.0 * f.function_hit / f.function_found END AS function_percent,
       f.line_hit, f.line_found, f.loaded
FROM resq_coverage_files AS f
JOIN resq_runs AS r ON r.run_id = f.run_id
WHERE (:'service' = '' OR r.service = :'service') AND (:'environment' = '' OR r.environment = :'environment') AND (:'branch' = '' OR r.vcs_branch = :'branch') AND r.finished_at = (
    SELECT MAX(r2.finished_at) FROM resq_runs AS r2
    JOIN resq_coverage_runs AS c2 ON c2.run_id = r2.run_id WHERE (:'service' = '' OR r2.service = :'service') AND (:'environment' = '' OR r2.environment = :'environment') AND (:'branch' = '' OR r2.vcs_branch = :'branch'))
ORDER BY function_percent, f.file_path LIMIT 25;

-- query:slowest_tests — Slowest tests (latest run)
SELECT t.suite, t.description, t.duration_seconds, t.attempts, t.file_path,
       t.execution_id
FROM resq_tests AS t JOIN resq_runs AS r ON r.run_id = t.run_id
WHERE (:'service' = '' OR r.service = :'service') AND (:'environment' = '' OR r.environment = :'environment') AND (:'branch' = '' OR r.vcs_branch = :'branch') AND r.finished_at = (
    SELECT MAX(r2.finished_at) FROM resq_runs AS r2 WHERE (:'service' = '' OR r2.service = :'service') AND (:'environment' = '' OR r2.environment = :'environment') AND (:'branch' = '' OR r2.vcs_branch = :'branch'))
ORDER BY t.duration_seconds DESC LIMIT 15;

-- query:failing_tests — Most-failing tests (selected range)
SELECT t.suite, t.description,
       SUM(CASE WHEN t.status IN ('fail', 'error') THEN 1 ELSE 0 END) AS failures,
       SUM(CASE WHEN t.flaky THEN 1 ELSE 0 END) AS flaky_passes,
       COUNT(*) AS runs, MAX(r.finished_at) AS last_seen, t.execution_id
FROM resq_tests AS t JOIN resq_runs AS r ON r.run_id = t.run_id
WHERE (:'service' = '' OR r.service = :'service') AND (:'environment' = '' OR r.environment = :'environment') AND (:'branch' = '' OR r.vcs_branch = :'branch')
GROUP BY t.test_id, t.case_id, t.suite, t.description, t.execution_id
HAVING SUM(CASE WHEN t.status IN ('fail', 'error') THEN 1 ELSE 0 END) > 0
    OR SUM(CASE WHEN t.flaky THEN 1 ELSE 0 END) > 0
ORDER BY failures DESC, flaky_passes DESC LIMIT 15;

-- query:newly_failing — Newly failing tests (latest vs previous run)
WITH history AS (
    SELECT t.execution_id, t.suite, t.description, t.status, t.file_path,
           r.finished_at,
           LAG(t.status) OVER (
               PARTITION BY t.execution_id ORDER BY r.finished_at) AS previous_status
    FROM resq_tests AS t JOIN resq_runs AS r ON r.run_id = t.run_id
    WHERE (:'service' = '' OR r.service = :'service') AND (:'environment' = '' OR r.environment = :'environment') AND (:'branch' = '' OR r.vcs_branch = :'branch'))
SELECT h.suite, h.description, h.previous_status, h.status, h.file_path,
       h.execution_id
FROM history AS h
WHERE h.finished_at = (SELECT MAX(r2.finished_at) FROM resq_runs AS r2 WHERE (:'service' = '' OR r2.service = :'service') AND (:'environment' = '' OR r2.environment = :'environment') AND (:'branch' = '' OR r2.vcs_branch = :'branch'))
  AND h.status IN ('fail', 'error') AND h.previous_status = 'pass'
ORDER BY h.suite, h.description LIMIT 25;

-- query:test_detail_history — Selected test duration history
SELECT r.finished_at AS time, t.duration_seconds
FROM resq_tests AS t JOIN resq_runs AS r ON r.run_id = t.run_id
WHERE (:'service' = '' OR r.service = :'service') AND (:'environment' = '' OR r.environment = :'environment') AND (:'branch' = '' OR r.vcs_branch = :'branch') AND (:'test' = '' OR t.execution_id = :'test')
ORDER BY r.finished_at;

-- query:test_detail_runs — Selected test executions
SELECT r.finished_at AS time, t.status, t.duration_seconds, t.attempts,
       t.flaky, t.message
FROM resq_tests AS t JOIN resq_runs AS r ON r.run_id = t.run_id
WHERE (:'service' = '' OR r.service = :'service') AND (:'environment' = '' OR r.environment = :'environment') AND (:'branch' = '' OR r.vcs_branch = :'branch') AND (:'test' = '' OR t.execution_id = :'test')
ORDER BY r.finished_at DESC LIMIT 50;

-- query:test_detail_attempts — Selected test attempts
SELECT a.started_at, a.attempt, a.status, a.duration_seconds, a.message
FROM resq_attempts AS a
JOIN resq_runs AS r ON r.run_id = a.run_id
WHERE (:'service' = '' OR r.service = :'service') AND (:'environment' = '' OR r.environment = :'environment') AND (:'branch' = '' OR r.vcs_branch = :'branch') AND (:'test' = '' OR a.execution_id = :'test')
ORDER BY a.attempt_key DESC LIMIT 100;

-- query:test_history — Per-test history
SELECT r.finished_at AS time, t.test_id, t.case_id, t.suite, t.description,
       t.status, t.duration_seconds, t.file_path
FROM resq_tests AS t JOIN resq_runs AS r ON r.run_id = t.run_id
WHERE (:'service' = '' OR r.service = :'service') AND (:'environment' = '' OR r.environment = :'environment') AND (:'branch' = '' OR r.vcs_branch = :'branch')
ORDER BY r.finished_at, t.test_id, t.case_id;

-- query:quarantine_debt — Quarantine and retry debt
SELECT r.finished_at AS time,
       (SELECT COUNT(*) FROM resq_tests AS t
         WHERE t.run_id = r.run_id AND t.quarantine_active) AS active_quarantines,
       (SELECT COUNT(*) FROM resq_tests AS t
         WHERE t.run_id = r.run_id AND t.retried) AS retried_tests
FROM resq_runs AS r WHERE (:'service' = '' OR r.service = :'service') AND (:'environment' = '' OR r.environment = :'environment') AND (:'branch' = '' OR r.vcs_branch = :'branch')
ORDER BY r.finished_at;

-- query:quarantined_tests — Active quarantines (latest run)
SELECT t.suite, t.description, t.status, t.quarantine_state,
       t.quarantine_owner, t.quarantine_reason, t.quarantine_issue,
       t.quarantine_expires_at
FROM resq_tests AS t JOIN resq_runs AS r ON r.run_id = t.run_id
WHERE (:'service' = '' OR r.service = :'service') AND (:'environment' = '' OR r.environment = :'environment') AND (:'branch' = '' OR r.vcs_branch = :'branch') AND t.quarantine_active AND r.finished_at = (
    SELECT MAX(r2.finished_at) FROM resq_runs AS r2 WHERE (:'service' = '' OR r2.service = :'service') AND (:'environment' = '' OR r2.environment = :'environment') AND (:'branch' = '' OR r2.vcs_branch = :'branch'))
ORDER BY t.quarantine_expires_at, t.suite, t.description;

-- query:benchmark_history — Benchmark medians
SELECT r.finished_at AS time, b.suite || ' :: ' || b.description AS metric,
       b.med_time_ms AS value
FROM resq_benchmarks AS b JOIN resq_runs AS r ON r.run_id = b.run_id
WHERE (:'service' = '' OR r.service = :'service') AND (:'environment' = '' OR r.environment = :'environment') AND (:'branch' = '' OR r.vcs_branch = :'branch')
  AND (:'benchmark' = '' OR b.benchmark_id = :'benchmark')
  AND (:'benchmark' <> '' OR b.benchmark_id IN (
      SELECT b2.benchmark_id FROM resq_benchmarks AS b2
      JOIN resq_runs AS r2 ON r2.run_id = b2.run_id
      WHERE (:'service' = '' OR r2.service = :'service') AND (:'environment' = '' OR r2.environment = :'environment') AND (:'branch' = '' OR r2.vcs_branch = :'branch')
      GROUP BY b2.benchmark_id
      ORDER BY MAX(b2.med_time_ms) DESC LIMIT 12))
ORDER BY r.finished_at, b.benchmark_id;

-- query:benchmark_verdicts — Benchmark verdicts per run
SELECT r.finished_at AS time,
       SUM(CASE WHEN b.comparison_class = 'regressed' THEN 1 ELSE 0 END) AS regressed,
       SUM(CASE WHEN b.comparison_class = 'inconclusive' THEN 1 ELSE 0 END) AS inconclusive,
       SUM(CASE WHEN b.comparison_class = 'improved' THEN 1 ELSE 0 END) AS improved,
       SUM(CASE WHEN b.comparison_class = 'stable' THEN 1 ELSE 0 END) AS stable
FROM resq_benchmarks AS b JOIN resq_runs AS r ON r.run_id = b.run_id
WHERE (:'service' = '' OR r.service = :'service') AND (:'environment' = '' OR r.environment = :'environment') AND (:'branch' = '' OR r.vcs_branch = :'branch')
GROUP BY r.finished_at ORDER BY r.finished_at;

-- query:diagnostics_trend — Framework diagnostics per run
SELECT r.finished_at AS time,
       SUM(CASE WHEN d.severity = 'error' THEN 1 ELSE 0 END) AS errors,
       SUM(CASE WHEN d.severity = 'warning' THEN 1 ELSE 0 END) AS warnings
FROM resq_diagnostics AS d JOIN resq_runs AS r ON r.run_id = d.run_id
WHERE (:'service' = '' OR r.service = :'service') AND (:'environment' = '' OR r.environment = :'environment') AND (:'branch' = '' OR r.vcs_branch = :'branch')
GROUP BY r.finished_at ORDER BY r.finished_at;

-- query:deployment_host — Branch/deployment/host correlation
SELECT r.finished_at AS time, r.service, r.environment, r.deployment_id,
       r.artifact_digest, r.vcs_sha, r.vcs_branch, r.hostname, r.q_version,
       r.os, r.ci_provider, r.ci_pipeline_id, r.fail_count, r.error_count
FROM resq_runs AS r WHERE (:'service' = '' OR r.service = :'service') AND (:'environment' = '' OR r.environment = :'environment') AND (:'branch' = '' OR r.vcs_branch = :'branch')
ORDER BY r.finished_at DESC;

-- query:qversion_annotations — q build annotations
SELECT MIN(r.finished_at) AS time,
       'q ' || r.q_version || ' / ' || r.os AS text
FROM resq_runs AS r WHERE (:'service' = '' OR r.service = :'service') AND (:'environment' = '' OR r.environment = :'environment') AND (:'branch' = '' OR r.vcs_branch = :'branch')
GROUP BY r.q_version, r.os ORDER BY time;

-- query:deploy_annotations — Deployment annotations
SELECT MIN(r.finished_at) AS time,
       'deploy ' || r.deployment_id || ' (' || r.vcs_branch || ' @ ' ||
       SUBSTR(r.vcs_sha, 1, 8) || ')' AS text
FROM resq_runs AS r
WHERE (:'service' = '' OR r.service = :'service') AND (:'environment' = '' OR r.environment = :'environment') AND (:'branch' = '' OR r.vcs_branch = :'branch') AND r.deployment_id <> ''
GROUP BY r.deployment_id, r.vcs_branch, r.vcs_sha
ORDER BY time;

-- query:coverage_context — Coverage by test context
SELECT r.finished_at AS time, c.context_id, c.test_id, t.status, m.kind,
       SUM(m.hits) AS hits
FROM resq_coverage_contexts AS c
JOIN resq_runs AS r ON r.run_id = c.run_id
LEFT JOIN resq_tests AS t ON t.run_id = c.run_id AND t.test_id = c.test_id
JOIN resq_coverage_context_metrics AS m
  ON m.coverage_context_key = c.coverage_context_key
WHERE (:'service' = '' OR r.service = :'service') AND (:'environment' = '' OR r.environment = :'environment') AND (:'branch' = '' OR r.vcs_branch = :'branch')
GROUP BY r.finished_at, c.context_id, c.test_id, t.status, m.kind
ORDER BY r.finished_at, c.context_id, m.kind;
